#include <Arduino.h>
#include <string.h>
#include <stdlib.h>

bool led = false;
bool blinking = false;
int duty = 0;
unsigned long blinkAt = 0;
char line[64];
unsigned int used = 0;
unsigned long lastByte = 0;
int rawButton = HIGH;
int stableButton = HIGH;
unsigned long buttonAt = 0;

void setLed(bool value) {
  led = value;
  digitalWrite(13, value ? HIGH : LOW);
}

void report() {
  Serial.print("LED=");
  Serial.print(led ? "ON" : "OFF");
  Serial.print(" PWM=");
  Serial.println(duty);
}

void executeCommand() {
  line[used] = '\0';
  if (strcmp(line, "ON") == 0) {
    blinking = false;
    setLed(true);
  } else if (strcmp(line, "OFF") == 0) {
    blinking = false;
    setLed(false);
  } else if (strcmp(line, "BLINK") == 0) {
    blinking = true;
    blinkAt = millis();
    setLed(true);
  } else if (strncmp(line, "PWM:", 4) == 0) {
    char *end;
    long value = strtol(line + 4, &end, 10);
    if (end != line + 4 && *end == '\0' && value >= 0 && value <= 255) {
      duty = (int)value;
      analogWrite(9, duty);
    }
  } else if (strcmp(line, "BUZZ") == 0) {
    tone(6, 1000, 200);
  } else if (strcmp(line, "STATUS") == 0) {
    report();
  }
  used = 0;
}

void setup() {
  pinMode(13, OUTPUT);
  pinMode(9, OUTPUT);
  pinMode(6, OUTPUT);
  pinMode(2, INPUT_PULLUP);
  setLed(false);
  analogWrite(9, duty);
  Serial.begin(9600);
}

void loop() {
  while (Serial.available() > 0) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') {
      if (used) executeCommand();
    } else if (used < sizeof(line) - 1) {
      line[used++] = c;
    }
  }
  unsigned long now = millis();
  if (used && now - lastByte >= 20) executeCommand();
  if (blinking && now - blinkAt >= 500) {
    blinkAt = now;
    setLed(!led);
  }
  int reading = digitalRead(2);
  if (reading != rawButton) {
    rawButton = reading;
    buttonAt = now;
  }
  if (reading != stableButton && now - buttonAt >= 30) {
    stableButton = reading;
    if (stableButton == LOW) report();
  }
}
